# --- replacement logic ---
def main():
    with open(FILE, 'r', encoding='utf-8') as f:
        content = f.read()

    # Pattern: capture each POI block and locate descriptionAdvanced inside.
    # We split by POI id, then for each POI replace hu and en lines inside descriptionAdvanced.
    # Strategy: find each `id: "<id>"` block, find next `descriptionAdvanced: {` ... matching `}` that ends a 4-lang object,
    # then within that block replace hu: "..." and en: "..." lines.

    new_content = content
    changed = 0
    for poi_id, langs in DATA.items():
        # Find this POI's block boundaries (from id to next id or end of array)
        idx = new_content.find(f'id: "{poi_id}"')
        if idx == -1:
            print(f"!! Not found: {poi_id}")
            continue
        # find descriptionAdvanced after idx
        da_idx = new_content.find('descriptionAdvanced:', idx)
        if da_idx == -1:
            print(f"!! No descriptionAdvanced for {poi_id}")
            continue
        # find opening brace
        brace_open = new_content.find('{', da_idx)
        # find matching close brace by counting
        depth = 0
        i = brace_open
        while i < len(new_content):
            c = new_content[i]
            if c == '{': depth += 1
            elif c == '}':
                depth -= 1
                if depth == 0:
                    brace_close = i
                    break
            i += 1
        else:
            print(f"!! Brace not closed for {poi_id}")
            continue

        block = new_content[brace_open+1:brace_close]
        new_block = block

        for lang in ('hu','en'):
            txt = langs.get(lang)
            if not txt: continue
            # match `lang: "..."` allowing escaped quotes (none expected since we control content)
            pattern = re.compile(rf'(\b{lang}\s*:\s*)"((?:[^"\\]|\\.)*)"')
            m = pattern.search(new_block)
            if not m:
                print(f"!! lang {lang} not found in block of {poi_id}")
                continue
            existing = m.group(2)
            # skip if existing is already good (>=50 chars AND no '?' broken AND not generic filler)
            generic_filler_marker = "is a remarkable feature of the geography"
            broken = '?' in existing and lang == 'hu'
            is_filler = generic_filler_marker in existing and lang == 'en'
            if len(existing) >= 50 and not broken and not is_filler:
                # already filled with native content, skip
                continue
            # ensure new text >= 600
            if len(txt) < 600:
                print(f"!! WARN {poi_id} {lang} only {len(txt)} chars")
            # escape quotes / backslashes in txt
            esc = txt.replace('\\','\\\\').replace('"','\\"')
            new_block = new_block[:m.start()] + m.group(1) + '"' + esc + '"' + new_block[m.end():]
        if new_block != block:
            new_content = new_content[:brace_open+1] + new_block + new_content[brace_close:]
            changed += 1

    with open(FILE, 'w', encoding='utf-8', newline='') as f:
        f.write(new_content)
    print(f"Updated POIs: {changed} / {len(DATA)} (x4 langs scope, hu+en written)")

if __name__ == '__main__':
    main()
